"""Generate rtl/aegis_ntt_rom.v (twiddle ROM) from model/ntt_hw.py.

  python gen_rom.py            write ../rtl/aegis_ntt_rom.v
  python gen_rom.py --check    exit 1 if the checked-in file differs
"""

import argparse
import os
import sys

import ntt_hw

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "rtl", "aegis_ntt_rom.v")


def render():
    lines = [
        "// SPDX-License-Identifier: Apache-2.0",
        "// GENERATED by hw/model/gen_rom.py -- do not edit by hand.",
        "//",
        "// Twiddle ROM for aegis_ntt. Address = {mode, k}:",
        "//   mode 0 (ML-KEM, q = 3329):    k = 1..127 -> 17^BitRev7(k) mod q",
        "//   mode 1 (ML-DSA, q = 8380417): k = 1..255 -> 1753^BitRev8(k) mod q",
        "//   k = 0 -> zetas[1] * f mod q (last NTT^-1 layer, final scaling merged;",
        "//            f = 3303 for ML-KEM, 8347681 for ML-DSA)",
        "// Registered output (one cycle latency).",
        "",
        "`timescale 1ns / 1ps",
        "",
        "module aegis_ntt_rom (",
        "    input             clk,",
        "    input      [8:0]  addr,",
        "    output reg [22:0] data",
        ");",
        "",
        "    always @(posedge clk) begin",
        "        case (addr)",
    ]
    for mbit, mode in ((0, "kem"), (1, "dsa")):
        tab = ntt_hw.rom_table(mode)
        kmax = 128 if mode == "kem" else 256
        for k in range(kmax):
            lines.append(f"            9'h{(mbit << 8) | k:03X}: data <= 23'd{tab[k]};")
    lines += [
        "            default: data <= 23'd0;",
        "        endcase",
        "    end",
        "",
        "endmodule",
        "",
    ]
    return "\n".join(lines)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    text = render()
    if args.check:
        try:
            with open(OUT) as f:
                cur = f.read()
        except FileNotFoundError:
            cur = None
        if cur != text:
            print(f"gen_rom.py: {os.path.normpath(OUT)} is out of date; run gen_rom.py", file=sys.stderr)
            return 1
        print("gen_rom.py: rtl/aegis_ntt_rom.v up to date")
        return 0
    with open(OUT, "w") as f:
        f.write(text)
    print(f"gen_rom.py: wrote {os.path.normpath(OUT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
